<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    apiKey: process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ANTHROPIC_API_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
